// Turn n8n's error object into something a human can act on.
//
// The important field is `leadRecoverable`: the lead itself is NOT lost when
// this workflow runs. The service has an idempotency ledger, so the original
// webhook can simply be redelivered, and completed steps will be skipped.
// Saying so here stops the 2am reaction of manually re-entering the lead and
// creating a duplicate contact.
const e = $input.first().json;
const execution = e.execution || {};
const lastNode = execution.lastNodeExecuted || 'unknown';

const transport = /ECONNREFUSED|ETIMEDOUT|ENOTFOUND|socket hang up|timeout/i
  .test(String(e.execution?.error?.message || ''));

return [{ json: {
  workflow: (e.workflow || {}).name || 'Lead Ops - GHL intake',
  executionId: execution.id || null,
  failedAt: lastNode,
  message: String(execution.error?.message || 'unknown error').slice(0, 500),
  stack: String(execution.error?.stack || '').slice(0, 1000),
  classification: transport ? 'service_unreachable' : 'workflow_error',
  leadRecoverable: true,
  nextStep: transport
    ? 'Check the LeadOps service and n8n network access, then redeliver the webhook.'
    : 'Open the execution, fix the workflow, then replay from /admin/dead-letters.',
  ts: new Date().toISOString(),
} }];

// Page the operator. Replace this node with Slack, PagerDuty or email as the
// client prefers - it is deliberately a Code node so the repository has no
// hard dependency on a paid notification service.
const j = $input.first().json;
const probe = j.statusCode ? ` (healthz returned ${j.statusCode})` : '';
console.error('[leadops] ALERT', JSON.stringify(j));
return [{ json: { alerted: true, channel: 'operator', detail: j, probe } }];

// A workflow-level bug rather than an outage: log it for the next working day
// instead of waking someone. The lead is already recorded on the service side.
const j = $input.first().json;
console.warn('[leadops] workflow error', JSON.stringify(j));
return [{ json: { logged: true, severity: 'warning', detail: j } }];
